	if value.AttemptID != attemptID {
		return QASynthesis{}, NewQAError(QAErrorInvalidState, "load synthesis", "QA synthesis identity does not match its path", nil)
	}
	return value, nil
}

func (store QAStore) readStrict(path, kind string, value any) error {
	info, err := os.Lstat(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return NewQAError(QAErrorInvalidState, "load "+kind, kind+" is missing", err)
		}
		return NewQAError(QAErrorPersistenceFailure, "load "+kind, "cannot inspect QA file", err)
	}
	if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 {
		return NewQAError(QAErrorInvalidState, "load "+kind, "QA file must be a regular private 0600 file", nil)
	}
	file, err := os.Open(path)
	if err != nil {
		return NewQAError(QAErrorPersistenceFailure, "load "+kind, "cannot open QA file", err)
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, qaHardStateBytes+1))
	if err != nil {
		return NewQAError(QAErrorPersistenceFailure, "load "+kind, "cannot read QA file", err)
	}
	if len(data) > qaHardStateBytes {
		return NewQAError(QAErrorBudgetExhausted, "load "+kind, "QA file exceeds the hard state limit", nil)
	}
	var header struct {
		SchemaVersion int `json:"schema_version"`
	}
	if err := json.Unmarshal(data, &header); err != nil {
		return NewQAError(QAErrorInvalidState, "load "+kind, "malformed QA JSON", err)
	}
	if header.SchemaVersion != QASchemaVersion {
		category := QAErrorUnknownSchema
		if header.SchemaVersion == 0 {
			category = QAErrorInvalidState
		}
		return NewQAError(category, "load "+kind, fmt.Sprintf("unsupported QA schema version %d", header.SchemaVersion), nil)
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(value); err != nil {
		return NewQAError(QAErrorInvalidState, "load "+kind, "malformed or unknown QA field", err)
	}
	var trailing any
	if err := decoder.Decode(&trailing); err == nil {
		return NewQAError(QAErrorInvalidState, "load "+kind, "multiple JSON values", nil)
	} else if !errors.Is(err, io.EOF) {
		return NewQAError(QAErrorInvalidState, "load "+kind, "trailing QA JSON", err)
	}
	return nil
}

type QAPublication struct {
	Map       *QAMap
	Shards    []QAShard
	Synthesis *QASynthesis
	State     QAState
	Flow      FlowState
}

func (store QAStore) Publish(publication QAPublication, token QAWriterToken) error {
	if err := store.checkWriter(token); err != nil {
		return err
	}
	if err := ValidateQAState(publication.State); err != nil {
		return NewQAError(QAErrorInvalidState, "publish", err.Error(), err)
	}
	if publication.State.Project != store.sprint.Project || publication.State.Sprint != store.sprint.Slug {
		return NewQAError(QAErrorInvalidState, "publish", "QA state scope does not match the selected sprint", nil)
	}
	if publication.Map != nil {
		if err := ValidateQAMap(*publication.Map); err != nil {
			return NewQAError(QAErrorInvalidState, "publish map", err.Error(), err)
		}
		path, err := store.mapPath(publication.Map.SemanticAttemptID)
		if err != nil {
			return err
		}
		digest, err := store.writeRecord("map", path, publication.Map, true)
		if err != nil {
			return err
		}
		publication.State.Map = &QAArtifactRef{Path: QAMapRelPath(store.sprint, publication.Map.SemanticAttemptID), Digest: digest}
		publication.State.CurrentAttemptID = publication.Map.SemanticAttemptID
	}
	sort.Slice(publication.Shards, func(i, j int) bool { return publication.Shards[i].ID < publication.Shards[j].ID })
	for i := range publication.Shards {
		shard := &publication.Shards[i]
		if err := ValidateQAShard(*shard); err != nil {
			return NewQAError(QAErrorInvalidState, "publish shard", err.Error(), err)
		}
		path, err := store.shardPath(shard.AttemptID, shard.ID)
		if err != nil {
			return err
		}
		if _, err := store.writeRecord("shard", path, shard, false); err != nil {
			return err
		}
	}
	if publication.Synthesis != nil {
		if err := ValidateQASynthesis(*publication.Synthesis, MaximumQABudgets()); err != nil {
			return NewQAError(QAErrorInvalidState, "publish synthesis", err.Error(), err)
		}
		path, err := store.synthesisPath(publication.Synthesis.AttemptID)
		if err != nil {
			return err
		}
		digest, err := store.writeRecord("synthesis", path, publication.Synthesis, false)
		if err != nil {
			return err
		}
		publication.State.Synthesis = &QAArtifactRef{Path: QASynthesisRelPath(store.sprint, publication.Synthesis.AttemptID), Digest: digest}
	}
	statePath, err := store.StatePath()
	if err != nil {
		return err
	}
	stateDigest, err := store.writeRecord("state", statePath, &publication.State, false)
	if err != nil {
		return err
	}
	publication.Flow.QA = qaFlowSummary(publication.State, stateDigest, store.sprint)
	if store.hooks.BeforeStep != nil {
		flowPath, _ := FlowStatePath(store.root, store.sprint)
		if err := store.hooks.BeforeStep("flow", flowPath); err != nil {
			return NewQAError(QAErrorPersistenceFailure, "publish flow summary", "flow summary publication was interrupted", err)
		}
	}
	if err := SaveFlowState(store.root, store.sprint, publication.Flow); err != nil {
		return NewQAError(QAErrorPersistenceFailure, "publish flow summary", "cannot publish QA flow summary", err)
	}
	return nil
}

// SaveRecoveredState is the explicit runtime-free recovery mutation. It can
// only record a non-active phase and never writes map, shard, or synthesis
// evidence. A previously validated completed state may be republished solely
// to reconcile its flow-summary pointer and digest.
func (store QAStore) SaveRecoveredState(state QAState, flow FlowState) error {
	switch state.Phase {
	case QAPhaseInterrupted, QAPhaseStale, QAPhaseInvalid, QAPhaseBlocked, QAPhaseCancelled, QAPhaseCompleted:
	default:
		return NewQAError(QAErrorInvalidState, "recover", "recovery cannot publish active QA state", nil)
	}
	if err := ValidateQAState(state); err != nil {
		return NewQAError(QAErrorInvalidState, "recover", err.Error(), err)
	}
	path, err := store.StatePath()
	if err != nil {
		return err
	}
	digest, err := store.writeRecord("state", path, &state, false)
	if err != nil {
		return err
	}
	flow.QA = qaFlowSummary(state, digest, store.sprint)
	if err := SaveFlowState(store.root, store.sprint, flow); err != nil {
		return NewQAError(QAErrorPersistenceFailure, "recover", "cannot publish recovered flow summary", err)
	}
	return nil
}

func (store QAStore) checkWriter(token QAWriterToken) error {
	if err := token.Validate(); err != nil {
		return NewQAError(QAErrorConflict, "publish", err.Error(), err)
	}
	if store.fence == nil {
		return NewQAError(QAErrorConflict, "publish", "no QA writer fence is configured", nil)
	}
	if err := store.fence(token); err != nil {
		return NewQAError(QAErrorConflict, "publish", "QA writer token is stale", err)
	}
	return nil
}

func (store QAStore) writeRecord(kind, path string, value any, immutable bool) (string, error) {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return "", NewQAError(QAErrorInvalidState, "publish "+kind, "cannot encode QA record", err)
	}
	data = append(data, '\n')
	if len(data) > qaHardStateBytes {
		return "", NewQAError(QAErrorBudgetExhausted, "publish "+kind, "QA record exceeds the hard state limit", nil)
	}
	if store.hooks.BeforeStep != nil {
		if err := store.hooks.BeforeStep(kind, path); err != nil {
			return "", NewQAError(QAErrorPersistenceFailure, "publish "+kind, "QA publication was interrupted", err)
		}
	}
	if immutable {
		current, readErr := os.ReadFile(path)
		if readErr == nil {
			if bytes.Equal(current, data) {
				return hashBytes(data), nil
			}
			return "", NewQAError(QAErrorConflict, "publish "+kind, "immutable QA map already exists with different bytes", nil)
		}
		if !errors.Is(readErr, fs.ErrNotExist) {
			return "", NewQAError(QAErrorPersistenceFailure, "publish "+kind, "cannot inspect existing QA record", readErr)
		}
	}
	if err := privateAtomicWrite(path, data, kind, store.hooks); err != nil {
		return "", NewQAError(QAErrorPersistenceFailure, "publish "+kind, "cannot atomically publish QA record", err)
	}
	return hashBytes(data), nil
}

func privateAtomicWrite(path string, data []byte, kind string, hooks QAStateHooks) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	for current := dir; ; current = filepath.Dir(current) {
		if err := os.Chmod(current, 0o700); err != nil {
			return err
		}
		if filepath.Base(current) == "verification" {
			break
		}
		parent := filepath.Dir(current)
		if parent == current {
			return fmt.Errorf("verification directory not found")
		}
	}
	temp, err := os.CreateTemp(dir, ".qa-"+kind+"-*.tmp")
	if err != nil {
		return err
	}
	tempPath := temp.Name()
	remove := true
	defer func() {
		if remove {
			_ = os.Remove(tempPath)
		}
	}()
	if err := temp.Chmod(0o600); err != nil {
		_ = temp.Close()
		return err
	}
	if _, err := temp.Write(data); err != nil {
		_ = temp.Close()
		return err
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(kind, path); err != nil {
			return err
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return err
	}
	remove = false
	syncDir(dir)
	return nil
}

func (store QAStore) verifyReference(ref QAArtifactRef) error {
	if filepath.IsAbs(ref.Path) || !validFingerprint(ref.Digest) {
		return NewQAError(QAErrorInvalidState, "load state", "invalid QA artifact reference", nil)
	}
	path, err := store.resolve(ref.Path)
	if err != nil {
		return err
	}
	digest, err := hashFile(path)
	if err != nil {
		return NewQAError(QAErrorPersistenceFailure, "load state", "cannot read referenced QA artifact", err)
	}
	if digest != ref.Digest {
		return NewQAError(QAErrorInvalidState, "load state", "QA artifact digest mismatch", nil)
	}
	return nil
}

func qaFlowSummary(state QAState, stateDigest string, sprint Sprint) *QAFlowSummary {
	return &QAFlowSummary{
		Phase: state.Phase, Fresh: state.Freshness.Current,
		CompletedShards: state.CompletedShards, TotalShards: state.TotalShards,
		Confirmed: state.OutcomeCounts[QATheoryConfirmed], Blocked: state.OutcomeCounts[QATheoryBlocked],
		Cancellation: state.Cancellation, StatePath: QAVerificationStateRelPath(sprint),
		StateDigest: stateDigest, CurrentAttemptID: state.CurrentAttemptID, NextAction: state.NextAction,
	}
}

package sprint

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type QAMapInput struct {
	Project                   string
	Sprint                    string
	ChangedPaths              []string
	ContextPaths              map[string][]string
	ExpectationRefs           []string
	RiskTags                  map[string][]string
	InputRefs                 []QAArtifactRef
	GovernedInputFingerprint  string
	ImplementationFingerprint string
	ReviewFingerprint         string
	PolicyFingerprint         string
	CheckCatalogFingerprint   string
	Target                    QATargetIdentity
	Settings                  QASettings
	ApprovedChecks            []QAApprovedCheckRef
}

type QAMapResult struct {
	Map             QAMap  `json:"map"`
	NormalizedBytes []byte `json:"-"`
	DryRun          bool   `json:"dry_run"`
}

// QAMap builds a deterministic map without accepting a run, constructing a
// runtime, or writing product state.
func (s Service) QAMap(projectRef, sprintRef string) (QAMapResult, error) {
	settings, err := s.effectiveQASettings()
	if err != nil {
		return QAMapResult{}, NewQAError(QAErrorInvalidState, "map", "effective QA settings are invalid", err)
	}
	manifest, findings, err := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
	if err != nil {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "cannot prepare governed Conformance Review inputs", err)
	}
	if len(findings) > 0 {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", fmt.Sprintf("governed inputs have %d validation findings", len(findings)), nil)
	}
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return QAMapResult{}, err
	}
	flow, err := LoadFlowState(s.root, sp)
	if err != nil {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "flow state is unavailable", err)
	}
	if flow.Review == nil || flow.Review.Stale || strings.TrimSpace(flow.Review.Fingerprint) == "" {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "a current Conformance Review record is required", nil)
	}
	switch flow.Review.Status {
	case ReviewCompleted, ReviewBlocked:
	default:
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "Conformance Review is not terminal", nil)
	}
	changed := normalizeQAStrings(manifest.ChangedPaths)
	if len(changed) == 0 || len(changed) == 1 && strings.HasPrefix(changed[0], "(") {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "execute evidence does not enumerate changed paths", nil)
	}
	implementationFingerprint, err := targetIdentity(manifest.Target)
	if err != nil {
		return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "target identity is unavailable", err)
	}
	inputRefs := make([]QAArtifactRef, 0, len(manifest.Inputs)+1)
	for _, input := range manifest.Inputs {
		if input.Hash == "" || input.Hash == "missing" {
			return QAMapResult{}, NewQAError(QAErrorStaleInput, "map", "governed input is missing: "+input.Path, nil)
		}
		inputRefs = append(inputRefs, QAArtifactRef{Path: filepath.ToSlash(input.Path), Digest: input.Hash})
	}
	if flow.Review.ArtifactDigest != "" {
		inputRefs = append(inputRefs, QAArtifactRef{Path: ArtifactRelPath(sp, StageReview), Digest: flow.Review.ArtifactDigest})
	}
	governedFingerprint, err := fingerprintQAValue(inputRefs)
	if err != nil {
		return QAMapResult{}, err
	}
	policyFingerprint, err := fingerprintQAValue(settings)
	if err != nil {
		return QAMapResult{}, err
	}
	context := qaAdjacentContext(manifest.Target, changed, settings.Budgets.ContextPathsPerShard)
	expectations := make([]string, 0, len(manifest.Coverage))
	for _, coverage := range manifest.Coverage {
		expectations = append(expectations, coverage.ID)
	}
	if len(expectations) == 0 {
		expectations = []string{"governed-plan"}
	}
	gitHead, gitIndex, gitWorktree := qaGitIdentity(manifest.Target)
	checks, err := ApprovedQAChecks(manifest.Target, changed, settings.Budgets)
	if err != nil {
		return QAMapResult{}, NewQAError(QAErrorInvalidState, "map", "approved check catalog is invalid", err)
	}
	checkRefs := make([]QAApprovedCheckRef, 0, len(checks))
	for _, check := range checks {
		checkRefs = append(checkRefs, QAApprovedCheckRef{ID: check.ID, Fingerprint: check.Fingerprint})
	}
	checkCatalogFingerprint, err := fingerprintQAValue(checks)
	if err != nil {
		return QAMapResult{}, err
	}
	input := QAMapInput{
		Project: sp.Project, Sprint: sp.Slug, ChangedPaths: changed, ContextPaths: context,
		ExpectationRefs: expectations, RiskTags: qaRiskTags(changed), InputRefs: inputRefs,
		GovernedInputFingerprint: governedFingerprint, ImplementationFingerprint: implementationFingerprint,
		ReviewFingerprint: flow.Review.Fingerprint, PolicyFingerprint: policyFingerprint,
		CheckCatalogFingerprint: checkCatalogFingerprint,
		Target:                  QATargetIdentity{Fingerprint: implementationFingerprint, GitHead: gitHead, GitIndex: gitIndex, GitWorktree: gitWorktree},
		Settings:                settings,
		ApprovedChecks:          checkRefs,
	}
	qaMap, err := BuildQAMap(input)
	if err != nil {
		return QAMapResult{}, err
	}
	data, err := NormalizedQAMapBytes(qaMap)
	if err != nil {
		return QAMapResult{}, err
	}
	return QAMapResult{Map: qaMap, NormalizedBytes: data, DryRun: true}, nil
}

func BuildQAMap(input QAMapInput) (QAMap, error) {
	if !safeQAName(input.Project) || !safeQAName(input.Sprint) {
		return QAMap{}, NewQAError(QAErrorInvalidState, "map", "invalid project or sprint identity", nil)
	}
	if err := ValidateQASettings(input.Settings); err != nil {
		return QAMap{}, NewQAError(QAErrorInvalidState, "map", err.Error(), err)
	}
	for name, value := range map[string]string{"governed input": input.GovernedInputFingerprint, "implementation": input.ImplementationFingerprint, "review": input.ReviewFingerprint, "policy": input.PolicyFingerprint, "check catalog": input.CheckCatalogFingerprint, "target": input.Target.Fingerprint} {
		if !validFingerprint(value) {
			return QAMap{}, NewQAError(QAErrorInvalidState, "map", "invalid "+name+" fingerprint", nil)
		}
	}
	paths := normalizeQAStrings(input.ChangedPaths)
	if len(paths) == 0 {
		return QAMap{}, NewQAError(QAErrorStaleInput, "map", "no changed paths were supplied", nil)
	}
	if len(paths) > input.Settings.Budgets.ChangedPaths {
		return QAMap{}, NewQAError(QAErrorBudgetExhausted, "map", "changed path limit exceeded", nil)
	}
	for _, path := range paths {
		if err := validateQAPath(path); err != nil {
			return QAMap{}, NewQAError(QAErrorInvalidState, "map", err.Error(), err)
		}
	}
	identity := QASemanticIdentity{GovernedInputFingerprint: input.GovernedInputFingerprint, ImplementationFingerprint: input.ImplementationFingerprint, ReviewFingerprint: input.ReviewFingerprint, PolicyFingerprint: input.PolicyFingerprint, ChangedPaths: paths}
	attemptID, err := NewQASemanticAttemptID(input.Project, input.Sprint, identity)
	if err != nil {
		return QAMap{}, err
	}
	mapID, err := NewQAMapID(input.Project, input.Sprint, attemptID, identity)
	if err != nil {
		return QAMap{}, err
	}
	type group struct {
		key     string
		unknown bool
		paths   []string
	}
	groupsByKey := map[string]*group{}
	for _, path := range paths {
		key, known := qaBehaviorGroup(path)
		if !known {
			key = "unknown/" + path
		}
		g := groupsByKey[key]
		if g == nil {
			g = &group{key: key, unknown: !known}
			groupsByKey[key] = g
		}
		g.paths = append(g.paths, path)
	}
	keys := make([]string, 0, len(groupsByKey))
	for key := range groupsByKey {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	var shards []QAShard
	owners := map[string]string{}
	for _, key := range keys {
		g := groupsByKey[key]
		for start := 0; start < len(g.paths); start += input.Settings.Budgets.ChangedPathsPerShard {
			end := start + input.Settings.Budgets.ChangedPathsPerShard
			if end > len(g.paths) {
				end = len(g.paths)
			}
			chunk := append([]string(nil), g.paths[start:end]...)
			concerns := []string{"changed behavior in " + key}
			phase := QAPhaseMapped
			var blocker *QABlocker
			if g.unknown {
				phase = QAPhaseBlocked
				blocker = &QABlocker{Category: QAErrorInvalidState, Scope: "shard", Summary: "unclassified changed path", NextAction: "Add a deterministic path classifier before investigation."}
				concerns = []string{"unclassified changed path"}
			}
			context := qaContextForPaths(input.ContextPaths, chunk, input.Settings.Budgets.ContextPathsPerShard)
			riskTags := qaTagsForPaths(input.RiskTags, chunk)
			shardIdentity := QAShardIdentity{Kind: QAShardPrimary, ChangedPaths: chunk, ContextPaths: context, BehavioralConcerns: concerns, ExpectationRefs: normalizeQAStrings(input.ExpectationRefs)}
			shardID, idErr := NewQAShardID(input.Project, input.Sprint, mapID, shardIdentity)
			if idErr != nil {
				return QAMap{}, idErr
			}
			shard := QAShard{SchemaVersion: 1, ID: shardID, AttemptID: attemptID, Kind: QAShardPrimary, Title: key, ChangedPaths: chunk, ContextPaths: context, BehavioralConcerns: concerns, ExpectationRefs: shardIdentity.ExpectationRefs, RiskTags: riskTags, ApprovedChecks: append([]QAApprovedCheckRef(nil), input.ApprovedChecks...), Phase: phase, Blocker: blocker}
			shards = append(shards, shard)
			for _, path := range chunk {
				owners[path] = shardID
			}
		}
	}
	if len(shards) > input.Settings.Budgets.PrimaryShards {
		return QAMap{}, NewQAError(QAErrorBudgetExhausted, "map", "primary shard limit exceeded", nil)
	}
	primaryCount := len(shards)
	if primaryCount > 1 && input.Settings.Budgets.BoundaryShards > 0 {
		overlap := make([]string, 0, primaryCount)
		for i := 0; i < primaryCount; i++ {
			overlap = append(overlap, shards[i].ChangedPaths[0])
		}
		if len(overlap) > input.Settings.Budgets.ContextPathsPerShard {
			overlap = overlap[:input.Settings.Budgets.ContextPathsPerShard]
		}
		boundaryIdentity := QAShardIdentity{Kind: QAShardBoundary, ContextPaths: overlap, BehavioralConcerns: []string{"cross-package integration"}, ExpectationRefs: normalizeQAStrings(input.ExpectationRefs)}
		boundaryID, idErr := NewQAShardID(input.Project, input.Sprint, mapID, boundaryIdentity)
		if idErr != nil {
			return QAMap{}, idErr
		}
		shards = append(shards, QAShard{SchemaVersion: 1, ID: boundaryID, AttemptID: attemptID, Kind: QAShardBoundary, Title: "cross-package integration", ContextPaths: overlap, OverlapPaths: overlap, BoundaryReason: "cross-package", BehavioralConcerns: boundaryIdentity.BehavioralConcerns, ExpectationRefs: boundaryIdentity.ExpectationRefs, RiskTags: qaTagsForPaths(input.RiskTags, overlap), ApprovedChecks: append([]QAApprovedCheckRef(nil), input.ApprovedChecks...), Phase: QAPhaseMapped})
	}
	if len(shards) > input.Settings.Budgets.TotalShards || len(shards) > input.Settings.Budgets.PendingEntries {
		return QAMap{}, NewQAError(QAErrorBudgetExhausted, "map", "planned shard or pending queue limit exceeded", nil)
	}
	sort.Slice(shards, func(i, j int) bool { return shards[i].ID < shards[j].ID })
	inputRefs := append([]QAArtifactRef(nil), input.InputRefs...)
	sort.Slice(inputRefs, func(i, j int) bool {
		if inputRefs[i].Path == inputRefs[j].Path {
			return inputRefs[i].Digest < inputRefs[j].Digest
		}
		return inputRefs[i].Path < inputRefs[j].Path
	})
	sources := append([]QAEffectiveSource(nil), input.Settings.Sources...)
	sort.Slice(sources, func(i, j int) bool { return sources[i].Field < sources[j].Field })
	coverage := QACoverage{ChangedPaths: paths, PrimaryOwners: owners, BoundaryOverlaps: map[string][]string{}}
	for _, shard := range shards {
		if shard.Kind == QAShardBoundary {
			coverage.BoundaryOverlaps[shard.ID] = append([]string(nil), shard.OverlapPaths...)
		}
		if shard.Blocker != nil {
			coverage.BlockedPaths = append(coverage.BlockedPaths, shard.ChangedPaths...)
		}
	}
	if len(coverage.BoundaryOverlaps) == 0 {
		coverage.BoundaryOverlaps = nil
	}
	coverage.BlockedPaths = normalizeQAStrings(coverage.BlockedPaths)
	result := QAMap{SchemaVersion: 1, ID: mapID, Project: input.Project, Sprint: input.Sprint, SemanticAttemptID: attemptID, GovernedInputFingerprint: input.GovernedInputFingerprint, ImplementationFingerprint: input.ImplementationFingerprint, ReviewFingerprint: input.ReviewFingerprint, PolicyFingerprint: input.PolicyFingerprint, CheckCatalogFingerprint: input.CheckCatalogFingerprint, Budgets: input.Settings.Budgets, EffectiveSources: sources, Target: input.Target, Coverage: coverage, Shards: shards, InputRefs: inputRefs}
	if err := ValidateQAMap(result); err != nil {
		return QAMap{}, NewQAError(QAErrorInvalidState, "map", err.Error(), err)
	}
	return result, nil
}

func NormalizedQAMapBytes(value QAMap) ([]byte, error) {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

func validateQAPath(path string) error {
	if filepath.IsAbs(path) || path == "." || path == ".." || strings.HasPrefix(filepath.ToSlash(filepath.Clean(filepath.FromSlash(path))), "../") || strings.ContainsAny(path, "\x00\r\n") {
		return fmt.Errorf("unsafe changed path %q", path)
	}
	return nil
}

func qaBehaviorGroup(path string) (string, bool) {
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(path)))
	ext := strings.ToLower(filepath.Ext(clean))
	switch ext {
	case ".go", ".md", ".html", ".js", ".css", ".yml", ".yaml", ".json", ".sh", ".sql":
	default:
		return "", false
	}
	parts := strings.Split(clean, "/")
	if len(parts) == 1 {
		return "root/" + ext, true
	}
	if parts[0] == "internal" || parts[0] == "cmd" {
		if len(parts) > 1 {
			return parts[0] + "/" + parts[1], true
		}
	}
	return parts[0], true
}

func qaContextForPaths(context map[string][]string, paths []string, limit int) []string {
	var values []string
	for _, path := range paths {
		values = append(values, context[path]...)
	}
	values = normalizeQAStrings(values)
	if len(values) > limit {
		values = values[:limit]
	}
	return values
}

func qaTagsForPaths(tags map[string][]string, paths []string) []string {
	var values []string
	for _, path := range paths {
		values = append(values, tags[path]...)
	}
	return normalizeQAStrings(values)
}

func qaAdjacentContext(target string, changed []string, limit int) map[string][]string {
	result := map[string][]string{}
	for _, path := range changed {
		var candidates []string
		if strings.HasSuffix(path, "_test.go") {
			candidates = append(candidates, strings.TrimSuffix(path, "_test.go")+".go")
		} else if strings.HasSuffix(path, ".go") {
			candidates = append(candidates, strings.TrimSuffix(path, ".go")+"_test.go")
		}
		for _, candidate := range candidates {
			if len(result[path]) >= limit {
				break
			}
			if info, err := os.Stat(filepath.Join(target, filepath.FromSlash(candidate))); err == nil && info.Mode().IsRegular() {
				result[path] = append(result[path], candidate)
			}
		}
	}
	return result
}

func qaRiskTags(paths []string) map[string][]string {
	result := map[string][]string{}
	for _, path := range paths {
		lower := strings.ToLower(filepath.ToSlash(path))
		var tags []string
		if strings.Contains(lower, "security") || strings.Contains(lower, "permission") || strings.Contains(lower, "config") {
			tags = append(tags, "security")
		}
		if strings.Contains(lower, "state") || strings.Contains(lower, "store") || strings.Contains(lower, "migration") {
			tags = append(tags, "persistence")
		}
		if strings.HasPrefix(lower, "internal/app/") || strings.HasPrefix(lower, "internal/web/") || strings.HasPrefix(lower, "cmd/") {
			tags = append(tags, "public-api")
		}
		if strings.Contains(lower, "runtime") || strings.Contains(lower, "process") {
			tags = append(tags, "runtime")
		}
		if strings.Contains(lower, "_test.") {
			tags = append(tags, "test")
		}
		result[path] = normalizeQAStrings(tags)
	}
	return result
}

func fingerprintQAValue(value any) (string, error) {
	data, err := canonicalQAJSON(value)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

func qaGitIdentity(target string) (head, index, worktree string) {
	read := func(args ...string) string {
		output, err := exec.Command("git", append([]string{"-C", target}, args...)...).Output()
		if err != nil {
			return ""
		}
		return strings.TrimSpace(string(output))
	}
	head = read("rev-parse", "HEAD")
	index = hashBytes([]byte(read("diff", "--cached", "--no-ext-diff")))
	worktree = hashBytes([]byte(read("status", "--short", "--untracked-files=all")))
	return head, index, worktree
}

func qaWorkspaceInputRef(root string, path string) QAArtifactRef {
	full, err := workspace.ResolveInside(root, path)
	if err != nil {
		return QAArtifactRef{Path: path, Digest: "invalid"}
	}
	digest, err := hashFile(full)
	if err != nil {
		return QAArtifactRef{Path: path, Digest: "missing"}
	}
	return QAArtifactRef{Path: filepath.ToSlash(path), Digest: digest}
}

package sprint

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

func BuildQAChallenge(project, sprint string, qaMap QAMap, identity QAChallengeIdentity) (QAChallenge, error) {
	identity.TheoryIDs = normalizeQAStrings(identity.TheoryIDs)
	identity.EvidenceRefs = normalizeQAStrings(identity.EvidenceRefs)
	identity.Claim = strings.TrimSpace(identity.Claim)
	identity.Basis = strings.TrimSpace(identity.Basis)
	identity.SafeEvidenceStrategy = strings.TrimSpace(identity.SafeEvidenceStrategy)
	id, err := NewQAChallengeID(project, sprint, qaMap.ID, identity)
	if err != nil {
		return QAChallenge{}, err
	}
	challenge := QAChallenge{SchemaVersion: QASchemaVersion, ID: id, MapID: qaMap.ID, TheoryIDs: identity.TheoryIDs, Claim: identity.Claim, Basis: identity.Basis, SafeEvidenceStrategy: identity.SafeEvidenceStrategy, EvidenceRefs: identity.EvidenceRefs}
	if err := ValidateQAChallenge(challenge, qaMap.Budgets); err != nil {
		return QAChallenge{}, err
	}
	return challenge, nil
}

func SynthesizeQA(qaMap QAMap, shards []QAShard) (QASynthesis, error) {
	return SynthesizeQAWithChallenges(qaMap, shards, nil)
}

// SynthesizeQAWithChallenges is pure for its normalized inputs. Challenger
// records can question theory groups, but cannot alter their retained outcome.
func SynthesizeQAWithChallenges(qaMap QAMap, shards []QAShard, challenges []QAChallenge) (QASynthesis, error) {
	if err := ValidateQAMap(qaMap); err != nil {
		return QASynthesis{}, NewQAError(QAErrorInvalidState, "synthesize", err.Error(), err)
	}
	shards = append([]QAShard(nil), shards...)
	sort.Slice(shards, func(i, j int) bool { return shards[i].ID < shards[j].ID })
	shardByTheory := map[string]QAShard{}
	var theories []QATheory
	var blockers []QABlocker
	for _, shard := range shards {
		if shard.AttemptID != qaMap.SemanticAttemptID {
			return QASynthesis{}, NewQAError(QAErrorStaleInput, "synthesize", "shard belongs to a different semantic attempt", nil)
		}
		if shard.Blocker != nil {
			blockers = append(blockers, *shard.Blocker)
		}
		for _, theory := range shard.Theories {
			if err := ValidateQATheory(theory); err != nil {
				return QASynthesis{}, NewQAError(QAErrorInvalidState, "synthesize", err.Error(), err)
			}
			shardByTheory[theory.ID] = shard
			theories = append(theories, theory)
		}
	}
	sort.Slice(theories, func(i, j int) bool { return theories[i].ID < theories[j].ID })
	theorySet := make(map[string]struct{}, len(theories))
	for _, theory := range theories {
		theorySet[theory.ID] = struct{}{}
	}
	challenges = append([]QAChallenge(nil), challenges...)
	if len(challenges) > qaMap.Budgets.FollowUpShards {
		return QASynthesis{}, NewQAError(QAErrorBudgetExhausted, "synthesize", "challenger record budget is exhausted", nil)
	}
	for i := range challenges {
		challenges[i].TheoryIDs = normalizeQAStrings(challenges[i].TheoryIDs)
		challenges[i].EvidenceRefs = normalizeQAStrings(challenges[i].EvidenceRefs)
		if err := ValidateQAChallenge(challenges[i], qaMap.Budgets); err != nil || challenges[i].MapID != qaMap.ID {
			return QASynthesis{}, NewQAError(QAErrorInvalidState, "synthesize", "challenger record is invalid or stale", err)
		}
		for _, theoryID := range challenges[i].TheoryIDs {
			if _, ok := theorySet[theoryID]; !ok {
				return QASynthesis{}, NewQAError(QAErrorStaleInput, "synthesize", "challenger record references a theory outside the current map", nil)
			}
		}
	}
	sort.Slice(challenges, func(i, j int) bool { return challenges[i].ID < challenges[j].ID })
	theoryIDs := make([]string, 0, len(theories))
	outcomeCounts := map[QATheoryOutcome]int{}
	groups := map[string][]QATheory{}
	for _, theory := range theories {
		theoryIDs = append(theoryIDs, theory.ID)
		outcomeCounts[theory.Outcome]++
		groups[qaTheoryEquivalenceKey(theory)] = append(groups[qaTheoryEquivalenceKey(theory)], theory)
	}
	deduplicated := map[string][]string{}
	var contradictions [][]string
	var followCandidates []QATheory
	keys := make([]string, 0, len(groups))
	for key := range groups {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		group := groups[key]
		ids := make([]string, 0, len(group))
		confirmed, refuted := false, false
		for _, theory := range group {
			ids = append(ids, theory.ID)
			confirmed = confirmed || theory.Outcome == QATheoryConfirmed
			refuted = refuted || theory.Outcome == QATheoryRefuted
			if theory.Outcome == QATheoryCrossShard || theory.Outcome == QATheoryInconclusive {
				followCandidates = append(followCandidates, theory)
			}
		}
		sort.Strings(ids)
		if len(ids) > 1 {
			deduplicated[ids[0]] = append([]string(nil), ids[1:]...)
		}
		if confirmed && refuted {
			contradictions = append(contradictions, ids)
		}
	}
	sort.Slice(contradictions, func(i, j int) bool {
		return strings.Join(contradictions[i], "\x00") < strings.Join(contradictions[j], "\x00")
	})
	interactions := qaSynthesisInteractions(theories, shardByTheory)
	sort.Slice(followCandidates, func(i, j int) bool { return followCandidates[i].ID < followCandidates[j].ID })
	if len(followCandidates) > qaMap.Budgets.FollowUpShards {
		followCandidates = followCandidates[:qaMap.Budgets.FollowUpShards]
	}
	followUps := make([]QAShard, 0, len(followCandidates))
	for _, theory := range followCandidates {
		parent := shardByTheory[theory.ID]
		context := normalizeQAStrings(append(append([]string(nil), parent.ChangedPaths...), parent.ContextPaths...))
		if len(context) > qaMap.Budgets.ContextPathsPerShard {
			context = context[:qaMap.Budgets.ContextPathsPerShard]
		}
		identity := QAShardIdentity{Kind: QAShardFollowUp, ContextPaths: context, BehavioralConcerns: []string{"follow up: " + theory.Claim}, ExpectationRefs: normalizeQAStrings(theory.ExpectationRefs), ParentTheoryIDs: []string{theory.ID}}
		id, err := NewQAShardID(qaMap.Project, qaMap.Sprint, qaMap.ID, identity)
		if err != nil {
			return QASynthesis{}, err
		}
		followUps = append(followUps, QAShard{SchemaVersion: 1, ID: id, AttemptID: qaMap.SemanticAttemptID, Kind: QAShardFollowUp, Title: "Follow up " + theory.ID, ContextPaths: context, BehavioralConcerns: identity.BehavioralConcerns, ExpectationRefs: identity.ExpectationRefs, ParentTheoryIDs: identity.ParentTheoryIDs, Phase: QAPhaseMapped})
	}
	sort.Slice(followUps, func(i, j int) bool { return followUps[i].ID < followUps[j].ID })
	followIDs := make([]string, 0, len(followUps))
	for _, shard := range followUps {
		followIDs = append(followIDs, shard.ID)
	}
	challengeIDs := make([]string, 0, len(challenges))
	for _, challenge := range challenges {
		challengeIDs = append(challengeIDs, challenge.ID)
	}
	synthesisID, err := NewQASynthesisID(qaMap.Project, qaMap.Sprint, qaMap.SemanticAttemptID, QASynthesisIdentity{MapID: qaMap.ID, TheoryIDs: theoryIDs, ChallengeIDs: challengeIDs, FollowUpIDs: followIDs, PolicyFingerprint: qaMap.PolicyFingerprint})
	if err != nil {
		return QASynthesis{}, err
	}
	next := "Inspect the retained theory outcomes."
	if len(followUps) > 0 {
		next = "Run the bounded parent-linked follow-up shards."
	} else if len(blockers) > 0 {
		next = "Inspect the retained shard blockers and resume only after their stated prerequisites are restored."
	}
	sort.Slice(blockers, func(i, j int) bool {
		return strings.Join([]string{string(blockers[i].Category), blockers[i].Scope, blockers[i].Summary}, "\x00") < strings.Join([]string{string(blockers[j].Category), blockers[j].Scope, blockers[j].Summary}, "\x00")
	})
	result := QASynthesis{SchemaVersion: 1, ID: synthesisID, AttemptID: qaMap.SemanticAttemptID, MapID: qaMap.ID, TheoryIDs: theoryIDs, Challenges: challenges, Deduplicated: deduplicated, Contradictions: contradictions, Interactions: interactions, FollowUpShards: followUps, OutcomeCounts: outcomeCounts, Blockers: blockers, NextAction: next}
	if len(result.Deduplicated) == 0 {
		result.Deduplicated = nil
	}
	if err := ValidateQASynthesis(result, qaMap.Budgets); err != nil {
		return QASynthesis{}, NewQAError(QAErrorInvalidState, "synthesize", err.Error(), err)
	}
	return result, nil
}

func NormalizedQASynthesisBytes(value QASynthesis) ([]byte, error) {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

func qaTheoryEquivalenceKey(theory QATheory) string {
	refs := normalizeQAStrings(theory.ExpectationRefs)
	return strings.ToLower(strings.Join([]string{strings.TrimSpace(theory.Claim), strings.TrimSpace(theory.VerificationSurface), strings.Join(refs, "\x00")}, "\x00"))
}

func qaSynthesisInteractions(theories []QATheory, owners map[string]QAShard) []string {
	var interactions []string
	for i := 0; i < len(theories); i++ {
		for j := i + 1; j < len(theories); j++ {
			left, right := owners[theories[i].ID], owners[theories[j].ID]
			if left.ID == right.ID {
				continue
			}
			if theories[i].Outcome == QATheoryCrossShard || theories[j].Outcome == QATheoryCrossShard || shareQAString(left.RiskTags, right.RiskTags) {
				interactions = append(interactions, fmt.Sprintf("%s <-> %s", theories[i].ID, theories[j].ID))
			}
		}
	}
	return normalizeQAStrings(interactions)
}

func shareQAString(left, right []string) bool {
	set := map[string]struct{}{}
	for _, value := range left {
		set[value] = struct{}{}
	}
	for _, value := range right {
		if _, ok := set[value]; ok {
			return true
		}
	}
	return false
}

